        protected override IEnumerable<object[]> GetRows()
        {
            foreach (var vent in Vents)
                yield return Explosion(vent.Id, vent.Map, vent.Geyser ? GeyserClass : HornitoClass, vent.X, vent.Y, vent.Z,
                    $"{(vent.Geyser ? "Geyser" : "Hornito")} eruption at {vent.VentClass} 0x{vent.Vent:X}",
                    minSeconds: vent.MinSeconds, maxSeconds: vent.MaxSeconds, damageMin: DamageMin, damageMax: DamageMax, radius: Radius);
        }
